package com.bank.channels.sse;

import org.springframework.http.MediaType;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.servlet.mvc.method.annotation.SseEmitter;
import java.io.IOException;

// SSE: one-way price broadcast to many dashboard watchers.
@RestController
@RequestMapping("/api/v1/ticker")
public class TickerController {

    @GetMapping(value = "/{symbol}", produces = MediaType.TEXT_EVENT_STREAM_VALUE)
    public SseEmitter ticker(@PathVariable String symbol) {
        SseEmitter emitter = new SseEmitter(0L);
        Thread.ofVirtual().start(() -> {
            try {
                for (int i = 0; i < 5; i++) {
                    emitter.send(SseEmitter.event().name("price")
                            .data("{\"symbol\":\"" + symbol + "\",\"pricePaise\":" + (245000 + i * 25) + "}"));
                    Thread.sleep(1000);
                }
                emitter.complete();
            } catch (IOException | InterruptedException e) {
                emitter.completeWithError(e);
            }
        });
        return emitter;
    }
}
