package com.bank.channels.ack;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.web.bind.annotation.*;

// The occasional client→server action lives as a plain REST call ALONGSIDE
// the one-way SSE stream, so the SSE channel stays simple.
@RestController
@RequestMapping("/api/v1/notifications")
public class AckController {

    private static final Logger log = LoggerFactory.getLogger(AckController.class);

    @PostMapping("/{userId}/ack/{alertId}")
    public String acknowledge(@PathVariable String userId, @PathVariable String alertId) {
        log.info("User {} acknowledged alert {}", userId, alertId);
        return "ACK_RECORDED";
    }
}
```

