package com.bank.channels.ws;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.web.socket.*;
import org.springframework.web.socket.handler.TextWebSocketHandler;

// WebSocket: TWO-WAY. Needed because the trader SENDS orders and RECEIVES
// fills interactively — a client→server real-time channel SSE cannot provide.
public class TradingHandler extends TextWebSocketHandler {

    private static final Logger log = LoggerFactory.getLogger(TradingHandler.class);

    @Override
    protected void handleTextMessage(WebSocketSession session, TextMessage message)
            throws Exception {
        log.info("Order in: {}", message.getPayload());
        session.sendMessage(new TextMessage(
                "{\"type\":\"FILL\",\"pricePaise\":245050}"));   // reply on same connection
    }
}
```
